import { FunctionalComponent } from 'preact';
import Button from '../../../../../shared/Button';
import styles from '../../styles.module.scss';

interface Props {
  onClose: () => void;
}

const InfoPopover: FunctionalComponent<Props> = ({ onClose }: Props) => {
  const isMac = navigator.platform.includes('Mac');
  return (
    <div className={`${styles.bookmarksInfoPopover} ${styles.topArrow}`} style={{ height: process.env.APP_PLATFORM === 'web' ? 200 : (process.env.APP_TYPE === 'lite' ? 330 : 200) }}>
      <span className={styles.popoverContent}>
        {process.env.APP_PLATFORM === 'web' ? null : (process.env.APP_TYPE === 'lite' ? <p>Click here to see your bookmarks</p> : null)}
        <p className={process.env.APP_PLATFORM === 'web' ? styles.firstParagraph : (process.env.APP_TYPE === 'lite' ? styles.secondParagraph : styles.firstParagraph)}>
          {process.env.APP_PLATFORM === 'web' ? 'Press' : (process.env.APP_TYPE === 'lite' ? 'Or press' : 'Press')} {isMac ? 'Command' : 'Ctrl'} + Shift + B to bring back your
          bookmarks bar.
        </p>
        {process.env.APP_PLATFORM === 'web' ? <></> : (process.env.APP_TYPE === 'lite' ? <footer>
          <Button variant="primary" className={styles.button} onClick={onClose}>
            Close
          </Button>
          <a
            href={'https://about.oceanhero.today/bookmarks-extension'}
            className={styles.moreOptions}
          >
            More options
          </a>
        </footer> : <></>)}
        <span className={styles.ps}>
          PS: We did not remove your bookmarks bar on purpose. Chrome does it
          automatically and we cannot do anything about it 🙈
        </span>
      </span>
    </div>
  );
};

export default InfoPopover;
